# -*- coding: utf-8 -*-
"""The template written to ``config.ini`` when no user config exists.

The template doubles as the source of default values: :func:`parse_config`
reads it into a ConfigParser first and layers the user's file on top, so
every key the game reads is guaranteed to exist.

SPDX-License-Identifier: GPL-2.0-or-later
"""
from __future__ import annotations

from .constants import VERSION

