# Fog of War is a world you can only learn by walking it. A braided
# grid of corridors is generated from a seed, and everything further
# than FOG_RADIUS cells from the walker is painted flat black - so two
# worlds that differ only somewhere far off draw the same pixels until
# somebody goes and looks. With FOG_PERSIST the ground stays lit once
# seen and a map builds up on screen; with it off - which is how it
# ships - only the circle around the walker is ever visible and the
# map has to be carried in your head, which is the whole of why this
# sits among the working memory tasks rather than the planning ones.
# The agent environment turns it back on, because a map that only
# grows is what makes the lit pixel count a measure of coverage. FOG_MOVES is how many moves a world allows, bumps into
# walls included - a bump spends a move and changes nothing else, on
# screen or off, which is deliberate: anything an agent could make
# happen without going somewhere new is something it would learn to do
# instead of exploring.
FOG_RADIUS = 2
FOG_MOVES = 400
FOG_WORLDS = 3
FOG_PERSIST = False

# The 3D Maze is the maze from inside it. The same generator deals
# the same mazes at the same rungs as the 2D Maze, but the screen is
# split: a first-person view cast one ray to a column on the left, and
# on the right a map of the whole maze - corridors, start, way out,
# every door and key in its colour. The map is drawn once when a maze
# is dealt and never touched again. It does not follow the player, it
# carries no marker saying where the player is, and it does not dim
# what has been walked. Keeping your place on it is the entire task:
# you know where you began and you know what you have done, so your
# position is determined by arithmetic you have to do yourself, once
# per action, without ever being shown the answer.
# Turning costs a step, which is why the par here is its own exact
# minimum over cell, facing and keys rather than the flat one on the
# maze - about 1.28 times it, measured across the ladder. With free
# turns a player would spin on the spot at every cell and read all
# four corridors for nothing. Bumping into a wall costs nothing, as in
# the 2D maze: the wall is plainly visible from where you stand.
# HERE_MARKS draws the keys and the way out as marks hanging in the
# corridor; they are the only landmarks there are, and turning them
# off leaves nothing at all to check a count of corridors against.
HERE_LEVEL = 2
HERE_TRIALS = 3
HERE_ADAPTIVE = True
HERE_MARKS = True

# 3D Sokoban is the warehouse from inside it, and it is the 2D game's
# own engine throughout: the same generator deals the same rooms at the
# same rungs, the same solver certifies them, and the same test says
# when a position is provably lost. What is new is where you stand.
# The screen splits: a first-person view cast one ray to a column on
# the left, and on the right a plan of the whole warehouse - walls,
# goals, where you came in, and where every box stood when the door
# shut behind you. The plan is drawn once when a level is dealt and
# never touched again, and that is a harder promise than the 3D Maze's
# because here the world moves too: every push you make leaves the plan
# a little further out of date, and nothing on screen ever corrects it.
# What you have to carry is not a position but a position and a world.
# Turning costs a step, so the par is in steps rather than in pushes -
# its own exact minimum over boxes, cell and facing, about three and a
# half times the flat game's push count, measured across the ladder.
# Past rung eight that search outgrows its budget and the par becomes a
# proven lower bound, which the screen says rather than hides.
# Walking into rock, or shoving a box that will not go, costs nothing.
# SOKO3D_MARKS hangs a ring in the corridor where a goal still wants a
# box; SOKO3D_TRAPS marks the squares a box dies on, on the plan, as
# training wheels - and they are worth rather more here than on the
# flat screen, since from inside a corridor a pocket is not something
# you can look at.
SOKO3D_LEVEL = 2
SOKO3D_TRIALS = 3
SOKO3D_ADAPTIVE = True
SOKO3D_MARKS = True
SOKO3D_TRAPS = False

# Freeform Tetris: a well TETRIS_COLUMNS wide and TETRIS_ROWS deep, far
# wider and far finer than a tetris well. Nothing is dealt at you:
# TETRIS_QUEUE pieces are on offer and you click the one that comes
# next. Rotation is continuous - hold Up or Down and the piece winds
# round at TETRIS_SPIN degrees a second through the whole circle, with
# TETRIS_DETENT degrees of detent at each quarter turn, because a piece
# square to the grid is the only kind whose cells are whole cells and
# so the only kind a gapless drop can be promised for. Set the detent
# to 0 and every angle in the circle is held exactly as wound, with S
# the way to square up on purpose. Every piece
# on offer is cut out of the board's own skyline and is checked, after
# every placement, to still have a drop that buries nothing; the count
# of those drops is printed under it and a piece left with none is cut
# again. TETRIS_RUNG picks the starting rung of a ladder that climbs by
# shape alone - rectangles, then notches, then dented combs across six
# columns. TETRIS_FALL is the gravity, and it is yours: no rung ever
# changes it. With TETRIS_ADAPTIVE a run of placements that leave no
# gap climbs a rung and gaps fall off one. TETRIS_GHOST outlines where
# the piece would land, in one colour when that buries nothing and
# another when it does.
TETRIS_RUNG = 1
TETRIS_COLUMNS = 72
TETRIS_ROWS = 32
TETRIS_PIECES = 25
TETRIS_QUEUE = 5
TETRIS_FALL = 2.5
TETRIS_SPIN = 150
TETRIS_DETENT = 7
TETRIS_ADAPTIVE = True
TETRIS_GHOST = True

# Crossed Wires is the one task that hands the player nothing. A
# marker on a grid that wraps round at every edge, a target to reach,
# and four or eight keys whose directions have been scrambled - and
# nothing on screen ever says how. The only way to learn what a key
# does is to spend a press finding out, and presses are budgeted: a
# round allows the shortest trip plus a few spare, so probing every
# key before committing costs more than the round can afford and
# committing without probing walks the wrong way. WIRES_LEVEL picks
# the keys, how the wiring is scrambled, how much is spare, and - at
# the top - whether the whole ring turns silently every few presses
# and whether one key stops working partway through. Those last two
# are what separate a player who keeps checking from one that
# identifies the wiring once and trusts it forever. WIRES_GRID draws
# the cell lines, which makes a step countable; the wrapping is not
# animated, because a step across an edge is one step and sliding it
# across the board would say otherwise.
WIRES_LEVEL = 3
WIRES_ROUNDS = 5
WIRES_ADAPTIVE = True
WIRES_GRID = True

# Sudoku, graded by what a puzzle actually forces rather than by how
# many blanks it has - the two barely correlate. A rating solver runs
# a stack of techniques cheapest-first (naked and hidden singles,
# locked candidates, naked and hidden subsets, fish) and reports the
# deepest one the puzzle made it reach; past that the puzzle is graded
# by how many branch points a propagating search still has to guess
# at. SUDOKU_LEVEL runs from a four-by-four that falls to singles up
# to a sixteen-by-sixteen with a hundred and fifty-six blanks that
# needs hundreds of guesses once the logic is spent. The top rungs
# take a second or two to deal, because there is no way to dig
# *towards* a difficulty - only to deal and rate. With
# SUDOKU_SHOW_CLASHES a digit that contradicts one of its peers is
# marked as soon as it is written; with it off nothing is checked
# until the grid is full, which is the real game and much harder.
SUDOKU_LEVEL = 3
SUDOKU_TRIALS = 3
SUDOKU_SHOW_CLASHES = True
SUDOKU_ADAPTIVE = True

