# Chain of Custody is one box among several and one bay to put it in.
# The box is ringed for a moment at the start and then looks like the
# rest of them, and the belt carries them all round a loop while the
# claw picks up and puts down. What is scored is whether the box that
# arrives is the box that was ringed - so the whole task is holding on
# to an identity nothing on the screen carries. Every rung deals more
# boxes than coats, so a colour narrows the field and never closes it,
# and the painter moves a box's coat on as it rides past, so following
# a colour loses the thread on its own. From CUSTODY_LEVEL four the
# bay also asks for a state: the charger clears the charge mark in one
# pass and leaves the box too hot, so the route is charger, then
# cooler, then bay, and cooling first is wasted. A claw cannot chase a
# box - both move a slot at a time - so picking one up means standing
# still and letting the loop bring it round. CUSTODY_BELT_SECONDS is
# how long a slot takes; lower is a faster belt and less time to think
# between steps. CUSTODY_MARK_SECONDS is how long the ring is up at
# the start, and is the one dial that makes the first look easier.
CUSTODY_LEVEL = 3
CUSTODY_TRIALS = 5
CUSTODY_BELT_SECONDS = 0.40
CUSTODY_MARK_SECONDS = 1.6
CUSTODY_ADAPTIVE = True

# Cookie Thief is one boy standing at a jar with his hand over it. One
# press is one cookie, taken on the beat you asked for it, and at a
# COOKIE_BEAT_SECONDS of a sixth of a second that is as fast as you can
# press. What you are watching is the door, and it only ever opens.
# Every cookie leaves a gap she would notice on its own and that part
# never closes again; taking them quickly is noisy on top of that, and
# that part dies away on a quiet beat. She comes the first beat the
# door reaches a number nobody is told - the range is shaded on the
# frame, so you can see you are into the part where she might be and
# not which press is the one. Up to COOKIE_LEVEL five she stands in the
# doorway for a beat or two first and leaving still saves you; from six
# there is no warning at all. A round is scored twice: the number asked
# for with no grab seen is the clean getaway and that is the bar, and
# the points are the margin - every cookie is worth one, including the
# ones past the quota, and every grab she saw costs two. Leaving is a
# key rather than a pause, so stopping is a decision.
COOKIE_LEVEL = 4
COOKIE_TRIALS = 5
COOKIE_BEAT_SECONDS = 0.16
COOKIE_SET_SECONDS = 0.8
COOKIE_ADAPTIVE = True

# Donkey is the 1981 original: a two-lane road, donkeys standing in
# it, and one key that puts you in the other lane. Hit one and the
# road is over. What the original had for difficulty was speed, and
# speed here is DONKEY_BEAT_SECONDS - a dial rather than a rung, so
# that a person and a learner stepping the road a piece at a time are
# playing the same ladder. What carries the ladder instead is the
# swerve: crossing takes rows, it cannot be called off, and while the
# car is across the middle a donkey in either lane hits it. So the row
# a donkey arrives on is a row you have to be clear of already. Up to
# DONKEY_LEVEL five the crossing is one row and swerving on sight of
# the donkey is perfect play; from six it is two rows and from ten
# three, and swerving on sight clears under a tenth of the roads.
# Higher rungs also lay more donkeys and more road to hold on over.
# DONKEY_BEAT_SECONDS is how long a drawn row takes. The rules run
# four times finer than that - the car and the donkey both have a
# length, and a hit is the two of them overlapping - so the road
# actually moves in quarter-rows and a collision is a collision rather
# than a row the car entered.
DONKEY_LEVEL = 3
DONKEY_TRIALS = 5
DONKEY_BEAT_SECONDS = 0.18
DONKEY_SET_SECONDS = 0.8
DONKEY_ADAPTIVE = True

# Two Hands is Donkey's road stood up into three dimensions, and the
# name is the task rather than the fiction: one tick takes one action,
# the wheel and the sights come out of that one budget, and what is
# being measured is how a player splits it. The road has three lanes,
# nine kinds of thing standing in them, a jump for the flat ones and a
# throttle - and the throttle matters because the road has a clock on
# it. TWOHANDS_LEVEL one and two are tall hazards only, three deals
# them two abreast, four brings the log a swerve cannot answer, six
# the two that cost without killing, seven the ramp, the pad and the
# coin; from eight the swerve widens and the clock tightens. The clock
# is set as a multiple of the road's own best line rather than as a
# pace, so every deal at a rung asks the same thing of you. Faster is
# worse for a swerve - it covers both lanes for a fixed number of
# ticks, so speed is road you are exposed over - and better for a
# jump, which has to be off the ground for the whole overlap. Targets
# drift over the horizon and are shot with the mouse; nothing up there
# can touch the car, so what the sky costs is attention and nothing
# else. Measured over sixty deals a rung: taking the sky only on the
# ticks the wheel had no use for costs the road nothing at all and
# gets more of the sky than taking it the moment anything is up there,
# which loses most of the roads. TWOHANDS_BEAT_SECONDS is how long a
# drawn row takes at one sub-row a tick; at the top gear the road
# comes four times that fast, which is why this default is more than
# twice Donkey's: at the pace the middle rungs ask for, a target is
# aloft for about two seconds and the mouse has to get there and back
# inside that.
TWOHANDS_LEVEL = 3
TWOHANDS_TRIALS = 5
TWOHANDS_BEAT_SECONDS = 0.40
TWOHANDS_SET_SECONDS = 1.2
TWOHANDS_ADAPTIVE = True

# Crossword and Scrabble both run on a word list fetched from Hugging
# Face rather than shipped: about 173,000 words ranked by how often
# they turn up in Google's 1-grams, and a definition apiece from which
# a clue is made. Run "python -m neural_workshop.wordlist" once to
# fetch and distil them; without it Scrabble falls back to a short
# built-in list of common words and Crossword says so rather than
# dealing a puzzle with no clues on it.
#
# CROSSWORD_LEVEL sets both the shape and the vocabulary. Low rungs
# are small grids of everyday words with letters given away; middle
# rungs are ordinary nine-by-nines; the top is a five-by-five word
# square - every row and every column a word - drawn from the whole
# list with two clues in five simply not given, so those entries have
# to come from their crossings. With CROSSWORD_SHOW_MISTAKES a letter
# that is not the answer's is marked as it is written; with it off
# nothing is checked until the grid is full.
CROSSWORD_LEVEL = 2
CROSSWORD_TRIALS = 3
CROSSWORD_SHOW_MISTAKES = True
CROSSWORD_ADAPTIVE = True

# Scrabble here is one position rather than a game: a board with a few
# words on it, a rack of seven, and one play. It is scored as a share
# of the best play that existed, which is computed exactly, so a rung
# cannot be passed by being told what good is. SCRABBLE_LEVEL moves
# three things at once - how obscure the best play may be, how much
# board there is to hook onto, and what share of the best pays. A
# player who knows only the three thousand commonest words and always
# finds the best play among them scores all of the optimum at level
# one and about two fifths of it at level ten. SCRABBLE_SHOW_PREMIUMS
# paints the double and triple squares; the standard letter values and
# distribution are used, and no blank tiles are dealt.
SCRABBLE_LEVEL = 3
SCRABBLE_TRIALS = 5
SCRABBLE_SHOW_PREMIUMS = True
SCRABBLE_ADAPTIVE = True

# Scramble corrupts a real sentence and asks for it back. The text is
# Simple English Wikipedia, fetched rather than shipped: run
# "python -m neural_workshop.sentences" once (it reads 46 MB of one
# parquet file and needs pyarrow, which nothing else here uses).
# Without it the task runs on about seventy sentences written into the
# source, which is enough to play and not enough to stop repeating.
#
# SCRAMBLE_LEVEL turns eight dials at once, and they do not all take
# the same thing away. The low rungs are the familiar jumbled-word
# trick - "the hrose is balck" - which turns out to remove almost no
# information at all: a reader that knows no English still gets 98
# words in a hundred back off the letters alone. What actually removes
# information is further up, where letters go missing, strangers are
# thrown in, the spaces move to the wrong places or vanish, and the
# words come out of order. At level twelve that same reader gets one
# word in eleven, and the rest has to come from knowing what a
# sentence is. SCRAMBLE_SHOW_COUNT prints how many words the answer
# has, which above level five is real help, because that is where the
# spaces stop telling you.
SCRAMBLE_LEVEL = 3
SCRAMBLE_TRIALS = 5
SCRAMBLE_SHOW_COUNT = True
SCRAMBLE_ADAPTIVE = True

# Overrun draws a sentence from the same Simple English Wikipedia text
# and slides it at the right-hand margin. Type it away and the line is
# hauled back by a word at a time; let the end of it cross and a life
# goes. Clear a whole sentence and a life comes back. You start with
# three.
#
# OVERRUN_LEVEL turns one dial and only one: how fast the line moves.
# Every level deals the same sentences out of the same vocabulary, so
# the ladder is a typing speed and can be read as one - level one asks
# for about nineteen words a minute and level twelve for about
# eighty-four, which is the range between hunting for the keys and not
# needing to look at them. The options screen prints the rate for the
# level chosen. A wave always starts with as much clear road ahead of
# it as it has characters, which is what stops a long sentence being a
# harder question than a short one at the same level.
OVERRUN_LEVEL = 4
OVERRUN_WAVES = 8
OVERRUN_ADAPTIVE = True

# Algebra runs from 3 + 4 to one integer in a box of ten to the
# twenty-eighth. What grows is not the size of the numbers - that is a
# clerical ladder with a calculator at the top of it - but how big a
# search the question hides its answer in. The coefficients stay small
# at every level on purpose.
#
# Levels one to six are arithmetic: adding, order of operations, signs,
# exact fractions, then a letter to find. From seven, two families
# alternate, because they are hard in different ways. The odd ones are
# symbolic: multiply out and gather up, ending in a cube in two
# letters. The even ones are modular: solve a congruence, then two,
# then six at once, where the remainder theorem says there is exactly
# one answer below the product of the moduli and nothing on earth will
# find it by looking.
#
# Answers are exact and marked exactly. 64/35 and 128/70 are the same
# answer; 1.828 is not an answer. A symbolic answer must also be
# gathered up - no brackets left - because the question and its own
# answer are the same expression, so anything less would mark the
# question copied back as right. ALGEBRA_SHOW_WORKING prints the
# derivation after a wrong answer, which is where the learning is.
ALGEBRA_LEVEL = 3
ALGEBRA_TRIALS = 6
ALGEBRA_SHOW_WORKING = True
ALGEBRA_ADAPTIVE = True

# Numberology starts with child-friendly generated sequences and has no final
# level. A perfect session advances the next session by one level.
NUMBEROLOGY_LEVEL = 1
NUMBEROLOGY_TRIALS = 6
NUMBEROLOGY_ADVANCE = True

# Syllogisms runs from "is this the same as that, or the opposite"
# to three claims joined by connectives over thirteen lines of
# premises. Twelve levels. The things reasoned about are named after
# ordinary English nouns, taken from the same word list the crossword
# and the Scrabble rack use - run "python -m neural_workshop.wordlist"
# once to fetch it, and until then they are named with made-up words
# instead. A real word does carry a belief, and the place that could
# be spent is the two categorical levels, where "no X is a Y" is how
# the world usually is; answering that way every time is measured at
# 0.13 and 0.17 against a guessing floor of 0.20, so believing the
# premises is a way of doing worse than a coin rather than a way
# round the level.
#
# Every level offers the same answers its family has, and *cannot be
# told* is one of them roughly as often as any other - premises that
# settle everything are premises nobody has to reason about. The two
# direction levels are the exception: they never leave a question
# open, so they do not offer that answer at all.
#
# Levels one to four are chains - same and opposite, more and less,
# then with premises written in the negative. Five and eight are
# categorical: all, no, and at least one. Six and nine walk a grid,
# flat and then in three dimensions. Ten asks whether two relations
# are the same kind of thing, and eleven and twelve join two and
# three claims with and, or, and exactly-one-of, where a claim can be
# true, false, or not settled.
#
# SYLLOGISM_SHOW_WORKING prints the lines that mattered afterwards -
# and for a "nothing follows", two worlds that both fit the premises
# and disagree, which is what nothing following means.
#
# SYLLOGISM_REAL_WORDS off names the things with made-up words
# instead, which is what this task did first and is not a worse task:
# it is the same one with the belief taken out. It is also what
# happens anyway on a machine with no word list fetched.
SYLLOGISM_LEVEL = 3
SYLLOGISM_TRIALS = 6
SYLLOGISM_SHOW_WORKING = True
SYLLOGISM_ADAPTIVE = True
SYLLOGISM_REAL_WORDS = True

# Trivia asks a general-knowledge question off TriviaQA and offers
# other questions' answers as the wrong ones. TRIVIA_LEVEL is the rung
# of a seven-rung ladder that turns two dials and nothing else: how
# many options there are, and whether the wrong ones have to be the
# same shape as the right one. Rungs one to three widen from two
# options to four with the wrong answers drawn from anywhere, which
# means a year is often the only date on the screen; from rung four
# they are drawn from answers of the same shape - years against years,
# names against names - so that what an option looks like stops
# saying anything about whether it is right. Rungs four to seven then
# widen again, to eight.
#
# The ladder is not over the questions. TriviaQA does not say which of
# its questions are hard and neither does this, so a rung says how
# much help the screen gives and nothing about what is being asked.
#
# TRIVIA_SHOW_ANSWER marks the right option afterwards, which is the
# only working there is here: the dataset gives an answer, not a
# derivation.
#
# With nothing fetched the game deals from the hundred and twenty
# questions written into neural_workshop/trivia.py, which will come
# round quickly. python -m neural_workshop.trivia fetches ten thousand
# of the dataset's own.
TRIVIA_LEVEL = 3
TRIVIA_TRIALS = 10
TRIVIA_SHOW_ANSWER = True
TRIVIA_ADAPTIVE = True

# Verbal Reasoning reads multiple-choice questions from the separately built
# VerbalIQDataset Parquet artifact. The corpus and pyarrow are both opened
# only after a run starts, so neither adds to Workshop startup time. Point
# NW_VERBAL_IQ_DATASET at another checkout or artifact when required.
VERBAL_REASONING_TRIALS = 6
VERBAL_REASONING_EXPLANATION = True

# The Marble Maze tips a wooden tray in three dimensions. MARBLE_MAZE_SHADOWS
# turns off the shadow-map pass on machines where it costs more than it is
# worth; the tray is still drawn in perspective either way, because the tilt
# is the control and a flat tray would be a different task.
MARBLE_MAZE_LEVEL = 1
MARBLE_MAZE_TRIALS = 5
MARBLE_MAZE_ADAPTIVE = True
MARBLE_MAZE_SHADOWS = True
# Nought means "however long the level says", which is between 45 and 140
# seconds. Any other number caps every tray at it.
MARBLE_MAZE_SECONDS = 0

######################################################################
# This is the end of the configuration file.
######################################################################
